#define TOTAL_TOKENS 50000000000ULL
#define K_DIM 64
#define EXPANDED_DIM 14336

typedef struct {
    int gpu_id;
    int num_gpus;
    ncclComm_t comm;
    cudaStream_t compute_stream;
    cudaStream_t comm_stream;

    __nv_fp8_e4m3 *d_embed_table;
    __nv_fp8_e4m3 *d_w_in[NUM_LAYERS];
    __nv_fp8_e4m3 *d_w_out[NUM_LAYERS];
    __nv_fp8_e4m3 *d_w_gate[NUM_LAYERS];
    float *d_norm_scale[NUM_LAYERS];

    __nv_fp8_e4m3 *d_act_fwd[NUM_LAYERS];
    __nv_fp8_e4m3 *d_grad_act[NUM_LAYERS];

    float *d_opt_m_in[NUM_LAYERS];
    float *d_opt_v_in[NUM_LAYERS];
    float *d_opt_m_out[NUM_LAYERS];
    float *d_opt_v_out[NUM_LAYERS];

    int32_t *d_tokens;
    int32_t *d_targets;
    float *d_loss;
} GPUWorkerContext;

__global__ void non_abelian_gauge_forward_kernel(
    const __nv_fp8_e4m3* __restrict__ input,
    const __nv_fp8_e4m3* __restrict__ weight,
    __nv_fp8_e4m3* __restrict__ output,
    int batch_seq,
    int dim_in,
    int dim_out
) {
    int tid = blockDim.x * blockIdx.x + threadIdx.x;
    int total_elements = batch_seq * dim_out;
    if (tid >= total_elements) return;

    int b_s = tid / dim_out;
    int out_c = tid % dim_out;

    float acc = 0.0f;
    int in_offset = b_s * dim_in;
    int w_offset = out_c * dim_in;

    #pragma unroll 16
    for (int i = 0; i < dim_in; ++i) {
        float in_v = (float)(input[in_offset + i]);
        float w_v = (float)(weight[w_offset + i]);
        acc += in_v * w_v;
    }

    float phase = sinf((float)out_c * 0.001f);
    acc = acc * cosf(phase) - acc * sinf(phase);

    output[tid] = (__nv_fp8_e4m3)acc;
}

__global__ void non_abelian_gauge_backward_kernel(
    const __nv_fp8_e4m3* __restrict__ grad_out,
    const __nv_fp8_e4m3* __restrict__ weight,
    __nv_fp8_e4m3* __restrict__ grad_in,
    int batch_seq,
    int dim_in,
    int dim_out
) {
    int tid = blockDim.x * blockIdx.x + threadIdx.x;
    int total_elements = batch_seq * dim_in;
    if (tid >= total_elements) return;

    int b_s = tid / dim_in;
    int in_c = tid % dim_in;

    float acc = 0.0f;
    int out_offset = b_s * dim_out;

    #pragma unroll 16
    for (int j = 0; j < dim_out; ++j) {
        float go_v = (float)(grad_out[out_offset + j]);
        float w_v = (float)(weight[j * dim_in + in_c]);
        float phase = sinf((float)j * 0.001f);
        float go_gauge = go_v * cosf(phase) - go_v * sinf(phase);
        acc += go_gauge * w_v;
    }

    grad_in[tid] = (__nv_fp8_e4m3)acc;
}

__global__ void fused_fp8_adamw_kernel(
    __nv_fp8_e4m3* __restrict__ weight,
    const float* __restrict__ grad,
    float* __restrict__ m,
    float* __restrict__ v,
    int size,
    float lr,
    float beta1,
    float beta2,
    float eps,
    float weight_decay,
    float scale_grad
) {
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    if (idx >= size) return;

    float g = grad[idx] * scale_grad;
    float m_t = beta1 * m[idx] + (1.0f - beta1) * g;
    float v_t = beta2 * v[idx] + (1.0f - beta2) * g * g;
    m[idx] = m_t;
    v[idx] = v_t;

    float w = (float)(weight[idx]);
    w -= lr * (m_t / (sqrtf(v_t) + eps) + weight_decay * w);
    weight[idx] = (__nv_fp8_e4m3)w;
}

void* worker_thread(void* arg) {
    GPUWorkerContext* ctx = (GPUWorkerContext*)arg;
    CHECK_CUDA(cudaSetDevice(ctx->gpu_id));
    CHECK_CUDA(cudaStreamCreate(&ctx->compute_stream));
    CHECK_CUDA(cudaStreamCreate(&ctx->comm_stream));

    size_t embed_bytes = (size_t)VOCAB_SIZE * EMBED_DIM * sizeof(__nv_fp8_e4m3);
    size_t in_proj_bytes = (size_t)EMBED_DIM * EXPANDED_DIM * sizeof(__nv_fp8_e4m3);
    size_t out_proj_bytes = (size_t)EXPANDED_DIM * EMBED_DIM * sizeof(__nv_fp8_e4m3);
    size_t act_bytes = (size_t)MICRO_BATCH_SIZE * SEQ_LEN * EXPANDED_DIM * sizeof(__nv_fp8_e4m3);

    CHECK_CUDA(cudaMalloc(&ctx->d_embed_table, embed_bytes));
    CHECK_CUDA(cudaMemset(ctx->d_embed_table, 1, embed_bytes));

    for (int l = 0; l < NUM_LAYERS; ++l) {
        CHECK_CUDA(cudaMalloc(&ctx->d_w_in[l], in_proj_bytes));
        CHECK_CUDA(cudaMalloc(&ctx->d_w_out[l], out_proj_bytes));
        CHECK_CUDA(cudaMalloc(&ctx->d_act_fwd[l], act_bytes));
        CHECK_CUDA(cudaMalloc(&ctx->d_grad_act[l], act_bytes));

        CHECK_CUDA(cudaMalloc(&ctx->d_opt_m_in[l], (size_t)EMBED_DIM * EXPANDED_DIM * sizeof(float)));
        CHECK_CUDA(cudaMalloc(&ctx->d_opt_v_in[l], (size_t)EMBED_DIM * EXPANDED_DIM * sizeof(float)));
        CHECK_CUDA(cudaMalloc(&ctx->d_opt_m_out[l], (size_t)EXPANDED_DIM * EMBED_DIM * sizeof(float)));
        CHECK_CUDA(cudaMalloc(&ctx->d_opt_v_out[l], (size_t)EXPANDED_DIM * EMBED_DIM * sizeof(float)));

        CHECK_CUDA(cudaMemset(ctx->d_w_in[l], 1, in_proj_bytes));
        CHECK_CUDA(cudaMemset(ctx->d_w_out[l], 1, out_proj_bytes));
        CHECK_CUDA(cudaMemset(ctx->d_opt_m_in[l], 0, (size_t)EMBED_DIM * EXPANDED_DIM * sizeof(float)));
        CHECK_CUDA(cudaMemset(ctx->d_opt_v_in[l], 0, (size_t)EMBED_DIM * EXPANDED_DIM * sizeof(float)));
        CHECK_CUDA(cudaMemset(ctx->d_opt_m_out[l], 0, (size_t)EXPANDED_DIM * EMBED_DIM * sizeof(float)));
        CHECK_CUDA(cudaMemset(ctx->d_opt_v_out[l], 0, (size_t)EXPANDED_DIM * EMBED_DIM * sizeof(float)));
    }

    size_t total_steps = TOTAL_TOKENS / (MICRO_BATCH_SIZE * SEQ_LEN * ctx->num_gpus);
    int threads_per_block = 256;

    for (size_t step = 0; step < total_steps; ++step) {
        for (int l = 0; l < NUM_LAYERS; ++l) {
            int total_fwd = MICRO_BATCH_SIZE * SEQ_LEN * EXPANDED_DIM;
            int blocks = (total_fwd + threads_per_block - 1) / threads_per_block;
            non_abelian_gauge_forward_kernel<<<blocks, threads_per_block, 0, ctx->compute_stream>>>(
                ctx->d_act_fwd[l], ctx->d_w_in[l], ctx->d_act_fwd[l],
                MICRO_BATCH_SIZE * SEQ_LEN, EMBED_DIM, EXPANDED_DIM
            );
        }

        for (int l = NUM_LAYERS - 1; l >= 0; --l) {
            int total_bwd = MICRO_BATCH_SIZE * SEQ_LEN * EMBED_DIM;
            int blocks = (total_bwd + threads_per_block - 1) / threads_per_block;
            non_abelian_gauge_backward_kernel<<<blocks, threads_per_block, 0, ctx->compute_stream>>>(
                ctx->d_act_fwd[l], ctx->d_w_out[l], ctx->d_grad_act[l],
                MICRO_BATCH_SIZE * SEQ_LEN, EMBED_DIM, EXPANDED_DIM
            );

            CHECK_NCCL(ncclAllReduce(
                (const void*)ctx->d_grad_act[l], (void*)ctx->d_grad_act[l],
                MICRO_BATCH_SIZE * SEQ_LEN * EMBED_DIM, ncclInt8, ncclSum,
                ctx->comm, ctx->compute_stream
            ));

            int total_params_l = EMBED_DIM * EXPANDED_DIM;
            int opt_blocks = (total_params_l + threads_per_block - 1) / threads_per_block;
            fused_fp8_adamw_kernel<<<opt_blocks, threads_per_block, 0, ctx->compute_stream>>>(
                ctx->d_w_in[l], (const float*)ctx->d_grad_act[l],
                ctx->d_opt_m_in[l], ctx->d_opt_v_in[l],
                total_params_l, 1e-4f, 0.9f, 0.95f, 1e-8f, 0.01f, 1.0f
            );
        }
        CHECK_CUDA(cudaStreamSynchronize(ctx->compute_stream));
    }

    for (int l = 0; l < NUM_LAYERS; ++l) {
        CHECK_CUDA(cudaFree(ctx->d_w_in[l]));
        CHECK_CUDA(cudaFree(ctx->d_w_out[l]));
        CHECK_CUDA(cudaFree(ctx->d_act_fwd[l]));
        CHECK_CUDA(cudaFree(ctx->d_grad_act[l]));
        CHECK_CUDA(cudaFree(ctx->d_opt_m_in[l]));
        CHECK_CUDA(cudaFree(ctx->d_opt_v_in[l]));
        CHECK_CUDA(cudaFree(ctx->d_opt_m_out[l]));
        CHECK_CUDA(cudaFree(ctx->d_opt_v_out[l]));
    }
    CHECK_CUDA(cudaFree(ctx->d_embed_table));
    CHECK_CUDA(cudaStreamDestroy(ctx->compute_stream));
    CHECK_CUDA(cudaStreamDestroy(ctx->comm_stream));
    return NULL;
}

int main(int argc, char** argv) {
    ncclComm_t comms[NUM_GPUS];
    int devs[NUM_GPUS] = {0, 1, 2, 3};
    CHECK_NCCL(ncclCommInitAll(comms, NUM_GPUS, devs));

    pthread_t threads[NUM_GPUS];
    GPUWorkerContext contexts[NUM_GPUS];

    for (int i = 0; i < NUM_GPUS; ++i) {
        contexts[i].gpu_id = i;
        contexts[i].num_gpus = NUM_GPUS;
        contexts[i].comm = comms[i];
        if (pthread_create(&threads[i], NULL, worker_thread, &contexts[i]) != 0) {
            fprintf(stderr, "Failed to create thread for GPU %d\n", i);
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < NUM_GPUS; ++i) {
        pthread_join(threads[i], NULL);
        CHECK_NCCL(ncclCommDestroy(comms[i]));
    }

    return 0;
}
