                total_params_in, 1e-4f, 0.9f, 0.95f, 1e-8f, 0.01f, 1.0f / (float)ctx->num_gpus
            );
        }
        CHECK_CUDA(cudaStreamSynchronize(ctx->compute_stream));
    }

    for (int l = 0; l < NUM_LAYERS; ++l) {
        CHECK_CUDA(cudaFree(ctx->d_w_in[l]));
        CHECK_CUDA(cudaFree(ctx->d_w_out[l]));
        CHECK_CUDA(cudaFree(ctx->d_act_fwd[l]));
        CHECK_CUDA(cudaFree(ctx->d_grad_act[l]));
        CHECK_CUDA(cudaFree(ctx->d_grad_w_in[l]));
        CHECK_CUDA(cudaFree(ctx->d_grad_w_out[l]));
        CHECK_CUDA(cudaFree(ctx->d_opt_m_in[l]));
        CHECK_CUDA(cudaFree(ctx->d_opt_v_in[l]));
        CHECK_CUDA(cudaFree(ctx->d_opt_m_out[l]));
        CHECK_CUDA(cudaFree(ctx->d_opt_v_out[l]));
    }
    CHECK_CUDA(cudaFree(ctx->d_embed_table));
    CHECK_CUDA(cudaStreamDestroy(ctx->compute_stream));
    CHECK_CUDA(cudaStreamDestroy(ctx->comm_stream));
    return NULL;
}

int main(int argc, char** argv) {
    ncclComm_t comms[NUM_GPUS];
    int devs[NUM_GPUS] = {0, 1, 2, 3};
    CHECK_NCCL(ncclCommInitAll(comms, NUM_GPUS, devs));

    pthread_t threads[NUM_GPUS];
    GPUWorkerContext contexts[NUM_GPUS];

    for (int i = 0; i < NUM_GPUS; ++i) {
        contexts[i].gpu_id = i;
        contexts[i].num_gpus = NUM_GPUS;
        contexts[i].comm = comms[i];
        if (pthread_create(&threads[i], NULL, worker_thread, &contexts[i]) != 0) {
            fprintf(stderr, "Failed to create thread for GPU %d\n", i);
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < NUM_GPUS; ++i) {
        pthread_join(threads[i], NULL);
        CHECK_NCCL(ncclCommDestroy(comms[i]));
    }

    return 0;
}
